class Solution {
  public double[] internalAngles(int[] sides) {
    int a = sides[0], b = sides[1], c = sides[2];
    if (a + b <= c || a + c <= b || b + c <= a) return new double[0];
    double[] angles = {
      Math.toDegrees(Math.acos((double) (b * b + c * c - a * a) / (2.0 * b * c))),
      Math.toDegrees(Math.acos((double) (a * a + c * c - b * b) / (2.0 * a * c))),
      Math.toDegrees(Math.acos((double) (a * a + b * b - c * c) / (2.0 * a * b)))
    };
    java.util.Arrays.sort(angles);
    return angles;
  }
}
